def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    if n < 10:
        if opp[-1] == 'D':
            return 'D'
        return 'C'

    last_opp = opp[-1]
    last_me = me[-1]

    opp_c_total = sum(1 for a in opp if a == 'C')
    opp_d_total = n - opp_c_total

    opp_streakD = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            opp_streakD += 1
        else:
            break

    dd_streak = 0
    if last_opp == 'D' and last_me == 'D':
        for i in range(n - 1, -1, -1):
            if me[i] == 'D' and opp[i] == 'D':
                dd_streak += 1
            else:
                break

    opp_def = sum(1 for a in opp[-10:] if a == 'D')
    me_def = sum(1 for a in me[-10:] if a == 'D')

    if opp_def >= 8:
        return 'D'

    if n >= 20:
        recent_opp_def = sum(1 for a in opp[-5:] if a == 'D')
        earlier_opp_def = sum(1 for a in opp[-20:-5:] if a == 'D')
        if recent_opp_def >= 3 and earlier_opp_def <= 2:
            return 'D'

    if last_opp == 'D' and last_me == 'C':
        if n >= 2 and me[-2] == 'D' and opp[-2] == 'D':
            if opp_c_total >= 1 and opp_streakD <= 8:
                return 'C'
            return 'D'

        if n >= 2 and me[-2] == 'C' and opp[-2] == 'D':
            return 'D'

        if opp_c_total >= 10 and opp_d_total <= 1 and opp_streakD == 1 and rng.random() < 0.3:
            return 'C'

        if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C':
            return 'D'

        if rng.random() < 0.8:
            return 'D'
        return 'C'

    if last_opp == 'D' and last_me == 'D':
        if n >= 2 and me[-2] == 'C' and opp[-2] == 'D':
            return 'D'

        if opp_c_total >= 1:
            if dd_streak >= 2 and opp_streakD <= 7:
                return 'C'

            if n >= 4 and opp[-3:-1] == ['C', 'C']:
                return 'C'

            if opp_d_total <= max(2, n // 3) and rng.random() < 0.35:
                return 'C'

        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            exploit = 0
            for i in range(n - 1, -1, -1):
                if me[i] == 'D' and opp[i] == 'C':
                    exploit += 1
                else:
                    break

            if opp_d_total == 0 and exploit == 1 and rng.random() < 0.45:
                return 'D'

            if exploit >= 2:
                return 'D'

        if me_def >= 6:
            if rng.random() < 0.3:
                return 'D'

        if opp_def >= 5:
            if rng.random() < 0.25:
                return 'D'

        return 'C'

    return 'C'
